#!/usr/bin/env python3
"""Fill an HWPX template by replacing {{placeholders}} with JSON data.

- Loads /root/inventory_data.json
- Replaces placeholders across all XML entries inside an HWPX (ZIP)
- For any modified <hp:p>, removes <hp:lineSegArray>/<hp:linesegarray> and any lineSeg children
- Repackages to /root/inventory_report_ready.hwpx

This script is intentionally conservative:
- Unknown placeholders are left intact and will fail the final verification.
"""

from __future__ import annotations

import json
import re
import zipfile
from typing import Any, Dict, Tuple
from xml.etree import ElementTree as ET

TEMPLATE_PATH = "/root/inventory_report_template.hwpx"
DATA_PATH = "/root/inventory_data.json"
OUTPUT_PATH = "/root/inventory_report_ready.hwpx"

HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
ET.register_namespace("hp", HWPML_NS)

PLACEHOLDER_RE = re.compile(r"\{\{(.*?)\}\}")


def flatten_json(obj: Any, prefix: str = "") -> Dict[str, Any]:
    flat: Dict[str, Any] = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            key = f"{prefix}.{k}" if prefix else str(k)
            flat.update(flatten_json(v, key))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            key = f"{prefix}[{i}]" if prefix else f"[{i}]"
            flat.update(flatten_json(v, key))
    else:
        flat[prefix] = obj
    return flat


def build_replacer(data: Dict[str, Any], flat: Dict[str, Any]):
    def replace_in_text(text: str | None) -> Tuple[str | None, bool]:
        if text is None or "{{" not in text:
            return text, False

        changed = False

        def repl(m: re.Match[str]) -> str:
            nonlocal changed
            key = m.group(1).strip()

            if key in flat:
                changed = True
                val = flat[key]
                return "" if val is None else str(val)

            # Also allow direct top-level keys (common in templates)
            if key in data:
                changed = True
                val = data[key]
                return "" if val is None else str(val)

            # Leave untouched; final verification will catch any remaining placeholders.
            return m.group(0)

        out = PLACEHOLDER_RE.sub(repl, text)
        return out, changed

    return replace_in_text


def local_name(tag: str) -> str:
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def strip_layout_cache(elem: ET.Element) -> bool:
    """Remove line segment cache elements under elem (recursive)."""
    removed = False
    for child in list(elem):
        ln = local_name(child.tag)
        if ln in ("lineSegArray", "linesegarray", "lineSeg", "lineseg"):
            elem.remove(child)
            removed = True
            continue
        if strip_layout_cache(child):
            removed = True
    return removed


def iter_paragraphs(root: ET.Element):
    for p in root.iter(f"{{{HWPML_NS}}}p"):
        yield p


def paragraph_text_nodes(p: ET.Element):
    return list(p.iter(f"{{{HWPML_NS}}}t"))


def replace_placeholders_in_xml(xml_bytes: bytes, replace_in_text) -> Tuple[bytes, bool]:
    """Return (new_xml_bytes, changed_any)."""
    try:
        root = ET.fromstring(xml_bytes)
    except ET.ParseError:
        # Fallback: textual replacement (rare)
        txt = xml_bytes.decode("utf-8", errors="replace")
        new_txt, changed = replace_in_text(txt)
        return (new_txt.encode("utf-8") if new_txt is not None else b""), changed

    changed_any = False

    # Paragraph-aware pass to handle placeholders that may be split across runs.
    for p in iter_paragraphs(root):
        t_nodes = paragraph_text_nodes(p)
        if not t_nodes:
            continue

        joined = "".join((t.text or "") for t in t_nodes)

        # Replace across the joined run text first.
        replaced, changed = replace_in_text(joined)
        if changed and replaced is not None:
            # Redistribute: keep all text in the first run, blank out the rest.
            t_nodes[0].text = replaced
            for t in t_nodes[1:]:
                if t.text:
                    t.text = ""

            # Clear stale layout cache for modified paragraph.
            strip_layout_cache(p)

            changed_any = True

    # General pass: replace in any remaining text/tail nodes anywhere.
    # If this changes content inside a paragraph, also clear its layout cache.
    for p in iter_paragraphs(root):
        modified_p = False
        for elem in p.iter():
            if elem.text:
                new_text, changed = replace_in_text(elem.text)
                if changed:
                    elem.text = new_text
                    modified_p = True
            if elem.tail:
                new_tail, changed = replace_in_text(elem.tail)
                if changed:
                    elem.tail = new_tail
                    modified_p = True

        if modified_p:
            strip_layout_cache(p)
            changed_any = True

    out = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out, changed_any


def main() -> None:
    with open(DATA_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)

    flat = flatten_json(data)
    replace_in_text = build_replacer(data, flat)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin, zipfile.ZipFile(
        OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED
    ) as zout:
        for info in zin.infolist():
            raw = zin.read(info.filename)
            if info.filename.lower().endswith(".xml") and b"{{" in raw:
                new_raw, _ = replace_placeholders_in_xml(raw, replace_in_text)
                zout.writestr(info, new_raw)
            else:
                zout.writestr(info, raw)

    # Final verification: ensure no placeholders remain anywhere in XML.
    remaining = []
    with zipfile.ZipFile(OUTPUT_PATH, "r") as z:
        for name in z.namelist():
            if name.lower().endswith(".xml"):
                content = z.read(name)
                if b"{{" in content:
                    remaining.append(name)

    if remaining:
        raise SystemExit(f"ERROR: placeholders remain in: {remaining}")


if __name__ == "__main__":
    main()

